update public.learning_paths
set
  title = 'Lodging / Hotel Operations',
  goal = 'Lodging / Hotel Operations',
  summary = 'This course prepares students to lead hotel rooms operations across the complete guest lifecycle. Students examine hotel ownership and affiliation, rooms-division organization, staffing and shift control, reservations and distribution, forecasting and inventory, front-office and guest-accounting processes, in-house service, housekeeping and laundry, service recovery, property technology, privacy and cybersecurity, night audit, performance metrics, quality assurance, safety and accessibility, facilities and sustainability, group and special-stay complexity, and cross-departmental decision making. A semester-long synthetic-property simulation integrates guest experience, employee well-being, operational control, asset care, and financial results.',
  data = $lodgjson${"slug": "lodging-hotel-operations", "title": "Lodging / Hotel Operations", "description": "This course prepares students to lead hotel rooms operations across the complete guest lifecycle. Students examine hotel ownership and affiliation, rooms-division organization, staffing and shift control, reservations and distribution, forecasting and inventory, front-office and guest-accounting processes, in-house service, housekeeping and laundry, service recovery, property technology, privacy and cybersecurity, night audit, performance metrics, quality assurance, safety and accessibility, facilities and sustainability, group and special-stay complexity, and cross-departmental decision making. A semester-long synthetic-property simulation integrates guest experience, employee well-being, operational control, asset care, and financial results.", "topics": [{"id": "85e7c207-010e-4e37-b8ab-48ebc31e1d5c", "type": "topic", "title": "Hotel Industry Structure, Ownership, Brands, and the Rooms Division", "description": "Hotel operations sit inside a network of owners, lenders, asset managers, brands, operators, employees, partners, regulators, and guests. This section gives students the structural vocabulary needed to understand who sets priorities, who controls the experience, and how the rooms division creates value.", "children": [{"id": "1d0292aa-eb0a-4a0c-aae8-791fb55bae2b", "type": "subtopic", "title": "Hotel classifications and operating contexts", "children": [{"id": "83977033-de78-46c2-8f74-db6880e33cff", "type": "concept", "title": "Full-service, select-service, limited-service, extended-stay, resort, convention, boutique, lifestyle, luxury, economy, and hostel models"}, {"id": "9b4195f9-1139-45b4-ba12-73a8c452c6d8", "type": "concept", "title": "Urban, airport, highway, destination, mixed-use, all-suite, wellness, casino where legal, and residential or vacation-rental contexts"}, {"id": "e73f7458-9ccb-47a1-9a92-4694805da4dd", "type": "concept", "title": "Class, scale, size, location, amenity set, length of stay, demand segment, seasonality, and service intensity"}], "description": "Students compare lodging products so that operating choices reflect the property's market, service promise, physical plant, demand pattern, and guest needs."}, {"id": "043cf09b-039d-4c81-b2bb-9b361f35a902", "type": "subtopic", "title": "Ownership, management, and affiliation", "children": [{"id": "0412214e-1add-428e-8469-b213d842c6e7", "type": "concept", "title": "Owned-and-operated, management contract, franchise, lease, independent, soft-brand, collection, and third-party management arrangements"}, {"id": "408f776b-a525-408a-b0e3-90d70f238805", "type": "concept", "title": "Owner, operator, brand, franchisor, franchisee, asset manager, lender, developer, association, and vendor interests"}, {"id": "01e19b6b-5508-4f38-b5c8-54f8be395e5e", "type": "concept", "title": "Management fees, franchise fees, brand standards, capital obligations, approval rights, performance tests, and conflicts of interest"}], "description": "This subtopic clarifies the economic and decision relationships behind a hotel name, because the guest-facing brand may not own or operate the property."}, {"id": "d2b4443f-473f-4819-9360-ed6941a2c085", "type": "subtopic", "title": "Rooms division purpose and interdependence", "children": [{"id": "8b31b03b-d911-4f61-af31-2ec67ed25106", "type": "concept", "title": "Reservations, front office, guest services, housekeeping, laundry, security, engineering, revenue, sales, finance, and technology interfaces"}, {"id": "fd5a3968-16e3-42c7-ab36-f88515a8a6ee", "type": "concept", "title": "Guest lifecycle, room status, service requests, information handoffs, recovery, revenue capture, cost control, and asset care"}, {"id": "52185744-5d9f-4525-9e1e-79681f26960c", "type": "concept", "title": "Guest value, employee experience, owner returns, brand promise, community impact, safety, and regulatory obligations"}], "description": "Students frame the rooms division as a coordinated service-and-control system rather than a set of isolated departments."}]}, {"id": "a5d346b8-222d-4b9a-98a2-3acd26fe9099", "type": "topic", "title": "Rooms Division Organization, Leadership, Staffing, and Shift Control", "description": "Reliable hotel service depends on clear accountability across a continuous, labor-intensive operation. Students learn how organization design, staffing, communication, and manager-on-duty discipline convert forecasts and standards into safe shifts.", "children": [{"id": "76d8e4e1-8993-4c87-804d-ecdc8d92b7a0", "type": "subtopic", "title": "Organization, roles, and decision rights", "children": [{"id": "aa1d740a-6a6f-4939-9203-5d0c192a7002", "type": "concept", "title": "Rooms division executive, front office manager, executive housekeeper, supervisors, agents, attendants, bell/door, concierge, PBX, security, and engineering roles"}, {"id": "3c53f3e7-7be0-493c-a1b1-c011322d3356", "type": "concept", "title": "Organization charts, job descriptions, spans of control, segregation of duties, empowerment limits, and escalation thresholds"}, {"id": "668d68a3-7fdb-4bb2-895c-e34800287e37", "type": "concept", "title": "Owned, managed, franchised, unionized, outsourced, multi-property, and cluster-service variations"}], "description": "Students map who owns each outcome and where decisions must be coordinated or escalated."}, {"id": "a8477851-084f-4fec-a50b-667100874232", "type": "subtopic", "title": "Workforce planning and productivity", "children": [{"id": "1ec13cb8-c912-42a4-a571-a05d470eb669", "type": "concept", "title": "Occupancy, arrivals, departures, stayovers, rooms out of order, service level, room type, group activity, and special projects as workload drivers"}, {"id": "0376dc31-a3e3-4ddc-96ff-a11b5aa541d3", "type": "concept", "title": "Labor standards, staffing guides, schedules, cross-training, relief pools, overtime, agency labor, call-ins, and schedule fairness"}, {"id": "8958c9cc-d21b-4710-87f8-fd0dc298bf81", "type": "concept", "title": "Rooms cleaned per paid hour, labor cost per occupied room, overtime, absence, quality, safety, turnover, and guest impact"}], "description": "This subtopic connects expected demand and workload to the right labor, skills, timing, and contingency capacity."}, {"id": "a9f5cd4e-a0e7-4dfb-a0b2-3e7cbba3ba7a", "type": "subtopic", "title": "Shift control and leadership routines", "children": [{"id": "1b5258e8-c6bd-4f31-ba93-ccad9a5ff743", "type": "concept", "title": "Pre-shift briefing, pass-on log, manager-on-duty report, occupancy board, VIP list, group resume, traces, alerts, and unresolved cases"}, {"id": "b15a3ec8-ecc1-40db-bce9-bd9a31b56206", "type": "concept", "title": "Visual controls, huddles, walk-throughs, queue monitoring, room-status meetings, break coverage, coaching, and recognition"}, {"id": "967a09e6-82e1-4fc2-8755-f26283904882", "type": "concept", "title": "Decision logs, handoff standards, escalation, incident command, after-action review, and next-shift readiness"}], "description": "Students practice the short-cycle management routines that maintain situational awareness and coordinated execution."}]}, {"id": "0884935f-5f5a-4949-befd-455333548cfe", "type": "topic", "title": "Reservations, Forecasting, Inventory, and Distribution Channels", "description": "Reservations translate future demand into commitments, room inventory, cash expectations, and prearrival service information. Students learn to control availability across channels while balancing guest trust, revenue opportunity, and operational capacity.", "children": [{"id": "af27df17-a129-423d-bde8-4dee38e7d54a", "type": "subtopic", "title": "Reservation lifecycle and controls", "children": [{"id": "86b9ae5a-474a-40ac-a795-ced0253146f0", "type": "concept", "title": "Individual, group, corporate, wholesale, package, loyalty, complimentary, walk-in, and guaranteed/non-guaranteed reservations"}, {"id": "7621486b-8072-4ae7-8ec2-288b85b9c1d3", "type": "concept", "title": "Dates, room type, rate plan, occupancy, payment guarantee, deposit, cancellation, accessibility features, preferences, and consent"}, {"id": "17670b9f-914f-4bee-85c3-080ac47c43a6", "type": "concept", "title": "Confirmation accuracy, change history, duplicate detection, waitlists, traces, prepayment, chargeback evidence, and audit trail"}], "description": "Students trace a booking from inquiry through confirmation, modification, cancellation, arrival, no-show, and record retention."}, {"id": "72989973-b5f7-4f86-be1e-9fb0be402ab8", "type": "subtopic", "title": "Forecasting and inventory decisions", "children": [{"id": "76841aca-3527-46a1-90b2-d0d7e32dd658", "type": "concept", "title": "Historical demand, booking pace, pickup, lead time, day of week, seasonality, events, groups, cancellations, no-shows, and wash"}, {"id": "306bd590-d924-4776-a011-47d0bb617c7f", "type": "concept", "title": "Room-type inventory, oversell limits, out-of-order/out-of-service rooms, length-of-stay controls, closed dates, and upgrade paths"}, {"id": "6dfeca50-db6a-4768-ba7c-258b1d4ef58e", "type": "concept", "title": "Forecast error, scenario ranges, displacement, sellout risk, walk cost, guest impact, staffing implications, and decision cadence"}], "description": "This subtopic uses pace and uncertainty to protect sellable inventory and prepare the operation."}, {"id": "260efc7c-7de2-4564-8ab3-9f49e7c2f6ab", "type": "subtopic", "title": "Distribution architecture and economics", "children": [{"id": "adb5b41c-5a6c-4e59-94dc-46c1332eef0a", "type": "concept", "title": "Direct web/voice/app, CRS, GDS, OTA, metasearch, wholesaler, tour operator, TMC, consortia, and channel manager"}, {"id": "49aa4975-8595-49b0-9816-16412727813f", "type": "concept", "title": "Agency, merchant, opaque, package, net-rate, commission, parity, allotment, free-sale, and closed-user-group models"}, {"id": "5098a1f6-ce59-4326-a1cb-d94e6d8f28d6", "type": "concept", "title": "Content and availability accuracy, commission, payment model, fraud, data access, cancellation, service ownership, and net revenue"}], "description": "Students map how hotel inventory reaches guests and evaluate channels on net contribution, control, and service consequences."}]}, {"id": "8c3220b1-4751-4280-9b22-e667fea2c9c3", "type": "topic", "title": "Prearrival, Arrival, Front Desk, and Guest Accounting", "description": "Arrival is both a human welcome and a control point for identity, accessibility, room assignment, payment, keys, information, and expectations. Students learn to make front-office processes warm, efficient, secure, and financially accurate.", "children": [{"id": "9314a2ed-5635-409b-9fa9-252ec7d8b87f", "type": "subtopic", "title": "Prearrival planning and room assignment", "children": [{"id": "4ebe2eb4-5f0c-4e65-9d10-2e85498876b1", "type": "concept", "title": "Arrival lists, room types, accessible-room features, special requests, preferences, loyalty recognition, VIPs, groups, and amenities"}, {"id": "3a5f2e34-85c4-4aac-b2a2-95d23db6f7e1", "type": "concept", "title": "Pre-registration, digital check-in, mobile key, upsell, transportation, messaging, payment authorization, and consent"}, {"id": "ddb31719-fdd6-41eb-94f5-8470c11ddedc", "type": "concept", "title": "Room assignment logic, housekeeping/engineering coordination, connecting rooms, early arrival, upgrades, and blocked-room governance"}], "description": "Students use reservation and operational information to prepare an inclusive, feasible arrival experience before the guest reaches the desk."}, {"id": "e72a7849-5c84-4b71-a8d1-edb5420b6b51", "type": "subtopic", "title": "Check-in, keys, and guest information", "children": [{"id": "c21de65b-bf0e-402b-b76a-3d8abc1d87d4", "type": "concept", "title": "Welcome, reservation verification, registration, identity checks, payment, incidental authorization, room readiness, and key issuance"}, {"id": "44bb1d3d-01fb-4342-80a4-5a760464a308", "type": "concept", "title": "Accessible communication, service animals, language access, wayfinding, hotel orientation, benefits, fees, policies, and emergency information"}, {"id": "62764109-312d-48d5-a6d6-378768acfe3d", "type": "concept", "title": "Queue design, express/mobile options, identity-protection scripts, key replacement controls, minors and third-party bookings, and exception handling"}], "description": "This subtopic combines hospitality with identity, security, privacy, and clear communication."}, {"id": "1a696e12-7165-4dbb-b1ff-38e3cfb30471", "type": "subtopic", "title": "Guest folios, payments, and departure", "children": [{"id": "8d523390-71cd-4819-acf0-b9ae056bbe25", "type": "concept", "title": "Guest, master, city-ledger, house, and group folios; routing, allowances, rebates, transfers, deposits, and split billing"}, {"id": "303b9eb0-26c2-4747-9942-6664b32e472d", "type": "concept", "title": "Posting, verification, authorization, tokenization concepts, PCI awareness, cash controls, foreign currency where relevant, and chargeback evidence"}, {"id": "2b54e8f2-3ee3-40e3-8256-1ea263d2e3b9", "type": "concept", "title": "Check-out, late departure, invoice delivery, billing questions, express settlement, credit balance, accounts receivable, and record retention"}], "description": "Students learn how charges move from operating outlets to a controlled guest account and a clear final settlement."}]}, {"id": "a5401249-1dfb-444b-b8ad-63553d4f1d95", "type": "topic", "title": "In-House Service, Concierge, Communications, and Guest Experience", "description": "A hotel stay is a sequence of requests, emotions, queues, handoffs, and moments of truth. Students learn to manage that sequence as one experience across departments, channels, cultures, and accessibility needs.", "children": [{"id": "258d2f76-a31b-4f95-a90b-3d95dc17ee50", "type": "subtopic", "title": "Guest journey and service blueprint", "children": [{"id": "740ce0a7-2ba7-4691-aa7b-13989c5cb9ae", "type": "concept", "title": "Dreaming, booking, prearrival, arrival, stay, departure, post-stay, and return stages"}, {"id": "c729bc0a-1234-457f-80ce-44b554147afd", "type": "concept", "title": "Guest goals, actions, emotions, waits, uncertainty, touchpoints, frontstage behaviors, backstage processes, systems, and evidence"}, {"id": "d4c3eb48-c001-4c3f-8c10-b4f079ef70a2", "type": "concept", "title": "Failure points, handoffs, service standards, recovery triggers, accessibility, measures, and accountable owners"}], "description": "Students make the invisible operating system visible so friction and ownership can be improved."}, {"id": "d4d09cb9-6112-45d5-8cb4-5bb2ef991293", "type": "subtopic", "title": "Concierge, guest services, and local knowledge", "children": [{"id": "523a2664-ce9f-4448-b786-bf58a8130191", "type": "concept", "title": "Bell, door, valet, transportation, luggage, concierge, club lounge, recreation, childcare referral, and business services"}, {"id": "f62841be-ec98-4299-af8b-2ff2a6ffa3d4", "type": "concept", "title": "Destination knowledge, reservations, ticketing, itineraries, accessibility information, cultural sensitivity, safety, commissions, and disclosure"}, {"id": "8d6dea3a-310a-4b4e-8704-c9afee6edeb8", "type": "concept", "title": "Request capture, confirmation, third-party quality, liability boundaries, vendor escalation, gratuity ethics, and follow-through"}], "description": "This subtopic develops judgment for recommendations, logistics, personalization, and responsible community connection."}, {"id": "01b9e3b0-fbff-4f33-909f-6d81d68ee2cc", "type": "subtopic", "title": "Omnichannel communication and service coordination", "children": [{"id": "76458e98-fb69-4ff1-8566-bfab126f0258", "type": "concept", "title": "Telephone etiquette, PBX, messaging, chat, email, in-app requests, wake-up calls, lost-property inquiries, and internal radio"}, {"id": "dfc443f6-4c4f-494e-b9a3-8d0112284b09", "type": "concept", "title": "Authentication, privacy, tone, response-time standards, translation, accessibility, consent, records, and escalation"}, {"id": "abe03d61-5420-4e28-a269-d9b74564eb3e", "type": "concept", "title": "Case ownership, work orders, dispatch, status visibility, duplicate avoidance, handoff closure, and satisfaction confirmation"}], "description": "Students manage one conversation across voice, desk, text, app, email, and departmental workflows."}]}, {"id": "77296417-013b-42a6-8b7a-c5dce77f633a", "type": "topic", "title": "Housekeeping Systems, Cleaning Science, Linen, and Room Readiness", "description": "Housekeeping protects health, comfort, brand trust, employee safety, room availability, and the physical asset. Students learn to manage cleaning as a measurable production-and-quality system with human and environmental consequences.", "children": [{"id": "d7989e9e-bfe1-47d2-bdc3-e9e77d4af023", "type": "subtopic", "title": "Room-status and cleaning workflow", "children": [{"id": "649e89ee-100c-40ee-97e7-f362e927536a", "type": "concept", "title": "Vacant clean/dirty, occupied clean/dirty, inspected, pickup, due out, stayover, do-not-disturb, sleep-out, skipper, out-of-order, and out-of-service statuses"}, {"id": "b4f79b93-e09f-4e99-af40-4ad831904ada", "type": "concept", "title": "Morning reports, section assignment, boards or mobile apps, turndown, rush rooms, early arrivals, late checkouts, credits, and reallocation"}, {"id": "12b0c0c2-d8c6-4547-8079-8aa7e922d3cb", "type": "concept", "title": "Room attendant, houseperson, inspector, supervisor, front desk, laundry, minibar, engineering, and security handoffs"}], "description": "Students coordinate assignments and inspections so sellable rooms are released accurately and on time."}, {"id": "858d6598-5d74-44ad-b86a-255ac502976b", "type": "subtopic", "title": "Cleaning science, safety, and infection prevention", "children": [{"id": "ff277395-898b-42dd-9f24-68716a09a7cb", "type": "concept", "title": "Soil identification, detergent/disinfectant distinction, dilution, contact time, high-touch points, cross-contamination, and verification"}, {"id": "2302316b-a5c9-41e0-883f-e6b6df98ab21", "type": "concept", "title": "Safety data sheets, labeling, ventilation, PPE, sharps/biohazards, bloodborne-pathogen procedures, chemical storage, and spill response"}, {"id": "37f99e2a-74cb-4a43-936c-1209032c2cd0", "type": "concept", "title": "Cart design, lifting, bed making, pushing/pulling, repetitive motion, slips, workload, heat, breaks, reporting, and hierarchy of controls"}], "description": "This subtopic grounds visible cleanliness in correct chemistry, sequence, dwell time, equipment, ergonomics, and exposure control."}, {"id": "b8c5ad38-a248-4ff2-ae9f-0a1a53d086ad", "type": "subtopic", "title": "Linen, amenities, inventory, and quality inspection", "children": [{"id": "12ef2b5c-58fc-4038-955f-48a072d17f1e", "type": "concept", "title": "Par levels, linen flow, laundry capacity, outsourcing, sorting, spotting, washing, drying, finishing, storage, and replacement"}, {"id": "59c181f9-f31e-485c-9fe5-dc8722941fc8", "type": "concept", "title": "Guest supplies, uniforms, chemicals, equipment, minibars where applicable, requisitions, cycle counts, shrinkage, and vendor controls"}, {"id": "854514c8-bf65-4139-8e1e-d742cb55c316", "type": "concept", "title": "Inspection sequence, defect taxonomy, scoring, rework, root cause, calibration, preventive maintenance, and trend reporting"}], "description": "Students balance availability and presentation with cost, loss, water, energy, waste, and supplier risk."}]}, {"id": "960f6084-dbd5-48e9-b6dd-146e08c079e4", "type": "topic", "title": "Service Recovery, Complaint Resolution, Loyalty, and Reputation", "description": "Service failures are tests of empathy, judgment, speed, fairness, and organizational learning. Students practice recovering the relationship while protecting evidence, reducing recurrence, and avoiding promises beyond their authority.", "children": [{"id": "291c7d5f-7f71-4055-9415-b505524c0833", "type": "subtopic", "title": "Complaint intake and de-escalation", "children": [{"id": "e6792dc8-338b-4c8b-896a-54a502a0c529", "type": "concept", "title": "Listen, acknowledge, clarify, empathize, apologize appropriately, verify facts, explain next steps, and set timing"}, {"id": "1d8c0af7-f4e5-4792-b23d-f246ce44948a", "type": "concept", "title": "Accessibility, culture, language, trauma awareness, privacy, dignity, bias, intoxication, aggression, and employee safety"}, {"id": "cc5fe50c-f446-49bb-bf43-3422e0f1b4df", "type": "concept", "title": "Immediate danger, medical issues, discrimination, harassment, theft, privacy breach, media contact, and legal-threat escalation"}], "description": "Students learn to hear the guest's concern accurately, stabilize emotion, and identify the desired and feasible resolution."}, {"id": "a9d0326d-dc24-4c37-a213-8eb136c05298", "type": "subtopic", "title": "Recovery design and empowerment", "children": [{"id": "7fc548bc-6c7c-426c-986b-f67f424ee6d2", "type": "concept", "title": "Correction, replacement, room move, service, information, apology, fee removal, refund, points, amenity, and follow-up"}, {"id": "c5a07bdd-e736-4dd5-97c4-0f7300eb86ec", "type": "concept", "title": "Authority limits, approval matrix, consistency, discretion, documentation, fraud patterns, tax/accounting treatment, and vendor recovery"}, {"id": "9e56d89d-13dd-47ee-9eab-ec9c283c8fba", "type": "concept", "title": "Recovery paradox limits, distributive/procedural/interactional justice, vulnerable guests, and no-retaliation principles"}], "description": "This subtopic matches remedies to harm, responsibility, relationship value, precedent, and operational feasibility."}, {"id": "cfd07791-0253-45d1-b6fa-4dc4f53af171", "type": "subtopic", "title": "Closed-loop learning and reputation", "children": [{"id": "100b4550-bfb7-47c5-a12d-1f22000b41e8", "type": "concept", "title": "Case coding, severity, owner, service-level agreement, root cause, corrective action, verification, and recurrence monitoring"}, {"id": "fc6a06db-8161-4234-936f-548863dfc5e8", "type": "concept", "title": "Surveys, review platforms, loyalty feedback, social listening, rating distribution, sentiment, response standards, and competitor context"}, {"id": "09fd1e30-ddda-4afe-8e62-a1621b643a49", "type": "concept", "title": "Authentic reviews, no suppression or fabrication, clear incentives, response privacy, escalation, trend dashboards, and learning reviews"}], "description": "Students convert cases and reviews into reliable operational improvements without manipulating public feedback."}]}, {"id": "e828d1cf-1706-43a0-adf3-93aae1802216", "type": "topic", "title": "PMS, Hotel Technology Stack, Data, Privacy, Cybersecurity, and Responsible AI", "description": "Hotel technology coordinates inventory, identity, service, access, payments, and reporting. Students learn the system architecture and controls needed to use automation and AI without sacrificing reliability, privacy, security, accessibility, or human accountability.", "children": [{"id": "e11bf5bf-d13b-4f3a-a61b-0690bb32713e", "type": "subtopic", "title": "PMS and integrated hotel systems", "children": [{"id": "6df37357-cf0e-4add-9410-9ede2e72ebd4", "type": "concept", "title": "PMS, CRS, booking engine, channel manager, RMS, POS, sales/catering, CRM/CDP, housekeeping, maintenance, PBX, locks, Wi-Fi, payment, and accounting systems"}, {"id": "9ea95fc8-be66-4336-b240-17f8a487f4dc", "type": "concept", "title": "Profiles, reservations, inventory, rates, room status, folios, interfaces, APIs, batch jobs, timestamps, identifiers, and source-of-truth decisions"}, {"id": "0ae90e7b-7e42-44ea-b7c4-c724678cdc78", "type": "concept", "title": "Interface monitoring, duplicate profiles, reconciliation, change control, vendor support, downtime, manual fallback, and recovery testing"}], "description": "Students map the property management system as part of a wider, failure-prone ecosystem rather than as a single screen."}, {"id": "92790c66-e0ca-48f2-97b7-c738e8eda0b5", "type": "subtopic", "title": "Data governance, privacy, and cybersecurity", "children": [{"id": "52f1be3b-e9c6-431a-9b7a-ece2a27a252c", "type": "concept", "title": "Data inventory, purpose, consent, minimization, accuracy, retention, deletion, access, portability, logging, and vendor processing"}, {"id": "b22be1d8-bb32-4977-9eb4-17af9a495d33", "type": "concept", "title": "Identity, payment, travel, location, loyalty, accessibility, preference, incident, employee, biometric, and children's data sensitivity"}, {"id": "958c5040-55e6-40a4-bb75-c3b9c2fea853", "type": "concept", "title": "Role-based access, least privilege, multifactor authentication, phishing, social engineering, patching, backups, incident response, and PCI DSS awareness"}], "description": "This subtopic teaches students to collect less, control access, recognize threats, and protect the guest and property across the data lifecycle."}, {"id": "dfe3a9b3-7436-41d3-a2df-85354e76fc5d", "type": "subtopic", "title": "Automation, analytics, and responsible AI", "children": [{"id": "2b96905a-2094-4388-addd-4249a4b20c1b", "type": "concept", "title": "Chatbots, translation, personalization, forecasting, task routing, scheduling, computer vision, voice, robotics, and generative assistants"}, {"id": "b1c4998a-03a8-406b-9f97-2df284971f16", "type": "concept", "title": "Accuracy, hallucination, bias, accessibility, explainability, intellectual property, prompt/data leakage, cyber risk, deskilling, and service authenticity"}, {"id": "3346937a-abb0-4abd-8e4f-a05eced633cf", "type": "concept", "title": "Approved use cases, human review, testing, monitoring, override, disclosure, appeal, audit trail, vendor evidence, and retirement criteria"}], "description": "Students evaluate whether a technology improves a defined decision or workflow and what new failure modes it creates."}]}, {"id": "1b62354f-e063-4d3e-b3d3-4f9a8471d8a5", "type": "topic", "title": "Night Audit, Internal Controls, Occupancy and Revenue Metrics, and P&L Linkage", "description": "The business day closes only when operating activity is complete, reconciled, and trustworthy. Students learn to perform night-audit logic, interpret rooms performance, and connect daily decisions to financial statements and management action.", "children": [{"id": "3bfa425a-dfd1-4b28-a7a6-b991610a60dc", "type": "subtopic", "title": "Business-day close and reconciliation", "children": [{"id": "13de86c5-e75a-4274-b4a4-6ef34874e53e", "type": "concept", "title": "Outstanding postings, no-shows, room/tax, packages, allowances, rebates, transfers, routing, deposits, paid-outs, and house accounts"}, {"id": "a831d85f-1cad-42f2-9a5a-bdf210fd56db", "type": "concept", "title": "PMS, POS, payment processor, cash, credit cards, direct bill, interfaces, room status, keys, and occupancy reconciliation"}, {"id": "1334e61b-0a80-4e0d-8aed-13ce92274ac4", "type": "concept", "title": "Exception reports, approvals, segregation of duties, audit evidence, backup, system close, distribution, and unresolved-item log"}], "description": "Students sequence the controls required to roll the hotel from one business date to the next."}, {"id": "d0523e82-16c4-4aa8-bc79-ee5994898a41", "type": "subtopic", "title": "Rooms metrics and benchmarking", "children": [{"id": "b011dfc4-c355-400d-92ab-559bbebb4930", "type": "concept", "title": "Rooms available/sold/revenue, occupancy, ADR, RevPAR, double occupancy, average length of stay, cancellation, no-show, and out-of-order percentage"}, {"id": "15f2a8a5-d5c9-4514-95bd-93c2c36e3a18", "type": "concept", "title": "Market penetration index, average rate index, revenue generation index, competitive set, fair share, ranking, and confidentiality"}, {"id": "af1bfeed-e5e6-432f-b895-615a7b809216", "type": "concept", "title": "Gross versus net revenue, room-type and segment mix, channel cost, complementary metrics, definition control, and false comparisons"}], "description": "This subtopic develops fluency in the measures that explain demand, rate, inventory, and relative performance."}, {"id": "b6d4a9ab-8f78-4f66-be3e-e35b443d7d61", "type": "subtopic", "title": "Departmental P&L and management analysis", "children": [{"id": "7a58667b-50e7-4658-998c-be886b912424", "type": "concept", "title": "Rooms revenue, allowances, payroll, benefits, contract labor, linen, laundry, guest supplies, commissions, reservations, and other expenses"}, {"id": "07085139-34ec-48d0-81e7-b5f0cdb38801", "type": "concept", "title": "Budget, forecast, actual, prior year, variance, volume/rate/mix, labor productivity, cost per occupied room, and flow-through"}, {"id": "c25c9e0c-2417-403c-9821-3e14e98be921", "type": "concept", "title": "USALI concepts, controllable versus allocated costs, departmental profit, GOP linkage, narrative explanation, and corrective action"}], "description": "Students connect operational variance to the rooms department and overall hotel economics using lodging-industry account structures."}]}, {"id": "a640e1a4-1ed3-42c0-b0d5-6abd3cd45190", "type": "topic", "title": "Safety, Security, Accessibility, Risk, Emergency, and Human-Trafficking Awareness", "description": "Hotels are open, complex environments where care and security must coexist. Students learn prevention, inclusive service, proportionate response, documentation, and escalation while recognizing that law, emergency protocols, and specialized investigations require qualified authority.", "children": [{"id": "41bee000-7afb-4f68-841a-b834cde3914a", "type": "subtopic", "title": "Security, keys, cash, privacy, and incident response", "children": [{"id": "be15f426-4a9e-4ac5-99ce-72a7696e42a4", "type": "concept", "title": "Master and guest keys, access logs, key replacement, restricted areas, visitor and contractor controls, lost property, safe deposit, and package handling"}, {"id": "e320b77d-5a86-4d62-b3e9-9e585a9d9d9d", "type": "concept", "title": "Cash, refunds, chargebacks, skimming, fraud, identity theft, social engineering, cyber-physical interfaces, CCTV, and privacy boundaries"}, {"id": "36d88fea-5fe7-4ff6-83f1-df52fa982b8c", "type": "concept", "title": "Incident intake, immediate safety, emergency services, manager/security notification, scene preservation, objective report, evidence custody, and follow-up"}], "description": "Students identify routine controls that protect guests, employees, information, property, and evidence without creating an unwelcoming environment."}, {"id": "f17d1364-8b78-4cfc-85c5-bacf563e5af1", "type": "subtopic", "title": "Accessible and inclusive lodging operations", "children": [{"id": "ce17c994-6c73-40f1-b202-d114c5abc21c", "type": "concept", "title": "Reservation information, accessible-room inventory, feature matching, room assignment, holds, equivalent service, and staff knowledge"}, {"id": "edfbf86b-968c-42a8-be54-9fbadb0892a6", "type": "concept", "title": "Mobility, hearing, vision, cognitive, communication, digital, dietary, service-animal, and transportation considerations"}, {"id": "283580a4-35bf-4235-b18e-0df58a94128a", "type": "concept", "title": "ADA Title III and 2010 Standards awareness, effective communication, reasonable modifications, web access, maintenance, testing, and escalation to qualified guidance"}], "description": "This subtopic treats accessibility as an end-to-end guest experience and operating obligation, not only a room-design feature."}, {"id": "a1059862-762f-417d-b0aa-7886ad6e6e21", "type": "subtopic", "title": "Emergency readiness and exploitation prevention", "children": [{"id": "dd71139f-0da3-4bea-81f7-ca2b2c660836", "type": "concept", "title": "Fire, severe weather, power/water/IT outage, medical event, infectious disease, violence, evacuation, shelter, reunification, and business continuity"}, {"id": "6dab2dd1-217c-405e-96c2-15c7daf47d16", "type": "concept", "title": "Emergency roles, communication redundancy, accessible evacuation, guest accountability, drills, supplies, mutual aid, media protocol, and after-action review"}, {"id": "4e02dda1-85ab-4a87-b1a5-d458e7512cc3", "type": "concept", "title": "Human-trafficking awareness, nonprofiling indicators, privacy and employee safety, property reporting protocol, DHS Blue Campaign resources, and no independent confrontation"}], "description": "Students practice a calm, trauma-informed response to low-frequency, high-consequence events and suspicious indicators."}]}, {"id": "ec66d602-12b5-4384-a31c-d27eaab9d9d3", "type": "topic", "title": "Brand Standards, Quality Assurance, Audits, and Continuous Improvement", "description": "Standards make a promise repeatable, but quality management must also surface local context, unintended burdens, and changing guest needs. Students learn to measure conformance, experience, process capability, and corrective action together.", "children": [{"id": "b3ff21fe-21c2-46d9-97b3-be1910963868", "type": "subtopic", "title": "Standards architecture and service execution", "children": [{"id": "f17d35c7-c311-4e59-8402-11ab9128bb7f", "type": "concept", "title": "Product, cleanliness, condition, safety, accessibility, service, communication, technology, loyalty, and sustainability standards"}, {"id": "4ec2837d-71f5-40ab-97fa-5867f8a2af92", "type": "concept", "title": "Standard operating procedures, checklists, job aids, scripts, judgment boundaries, local adaptation, waivers, and version control"}, {"id": "9f445b62-06a2-41a7-b9db-c8558826edc3", "type": "concept", "title": "Training, tools, staffing, maintenance, supplier specifications, employee feedback, readiness checks, and accountable ownership"}], "description": "Students translate brand and property promises into observable, trainable, resourced behaviors and conditions."}, {"id": "aed82804-cc83-40b9-b72d-db454d8c5e9c", "type": "subtopic", "title": "Quality measurement and auditing", "children": [{"id": "bf5b5825-46e2-4e6e-a5c4-936851f89941", "type": "concept", "title": "Self-inspection, supervisor inspection, brand audit, mystery shop, guest feedback, complaint data, defect/rework, and operational observation"}, {"id": "f8546c30-877f-403d-8c52-9f9d2b01ce22", "type": "concept", "title": "Sampling, calibration, evidence, scoring, severity, critical failures, consistency, bias, gaming, and appeal"}, {"id": "8b1942fa-62f8-4694-863f-e2df29299f6e", "type": "concept", "title": "Reliability, responsiveness, assurance, empathy, tangibles, effort, satisfaction, recommendation, repeat intent, and behavioral evidence"}], "description": "This subtopic combines audits with guest, employee, financial, and process evidence so scores do not become the only goal."}, {"id": "11685209-189b-4921-8ad1-d6f4d8f5b4a2", "type": "subtopic", "title": "Problem solving and continuous improvement", "children": [{"id": "3dc84221-25c4-439c-b565-799944769f3d", "type": "concept", "title": "Problem statement, current condition, standard, gap, stratification, Pareto, process map, five whys, fishbone, and direct observation"}, {"id": "8d9a3a1c-f0ae-4c89-8ca9-fe3ebd2ad9b6", "type": "concept", "title": "Countermeasure, owner, due date, pilot, risk assessment, standard work, training, change communication, and control plan"}, {"id": "328ce675-c5e8-4f35-8e9a-da1efe5ba644", "type": "concept", "title": "Plan-do-study-act, leading/lagging measures, unintended effects, verification, sustainment audit, and knowledge sharing"}], "description": "Students move from symptoms to verified causes and sustainable process change."}]}, {"id": "be00ef8e-31bd-4072-be76-dc7ddd65e22a", "type": "topic", "title": "Facilities, Maintenance, Sustainability, Asset Protection, and Capital Planning", "description": "The guestroom product is a physical asset consumed every day. Students learn how rooms operations, engineering, finance, ownership, and sustainability systems coordinate to protect availability, safety, comfort, and long-term value.", "children": [{"id": "1ac81c2f-f0e0-4790-8c7d-5d9f3790bdee", "type": "subtopic", "title": "Preventive maintenance and room availability", "children": [{"id": "24133de1-3144-4519-a695-b2997223adfe", "type": "concept", "title": "Guestroom, corridor, public-area, elevator, HVAC, plumbing, electrical, lighting, locks, life-safety, pool/spa, and exterior systems"}, {"id": "292adc28-15e2-4795-b0a9-7be214afb14c", "type": "concept", "title": "Work requests, priority, dispatch, access, parts, technician notes, quality check, reopening, backlog, and repeat-defect analysis"}, {"id": "2a98022f-aae3-4728-8059-35b8665cbbdf", "type": "concept", "title": "Out-of-order versus out-of-service governance, downtime, lost room revenue, preventive schedules, inspections, and condition index"}], "description": "Students connect defect capture and planned maintenance to fewer guest failures and more sellable inventory."}, {"id": "9009eacb-f98c-472f-8e01-a0187c27112a", "type": "subtopic", "title": "Resource efficiency and sustainable operations", "children": [{"id": "4b26eec4-0816-4ed6-b22a-7c005b2fc365", "type": "concept", "title": "Energy, water, waste, linen/towel programs, chemicals, refrigerants, indoor air, biodiversity, purchasing, food/amenity waste, and single-use materials"}, {"id": "07174b51-0078-41c0-8d75-49fcb2f689b3", "type": "concept", "title": "Meters, baselines, intensity measures, targets, occupancy/weather normalization, audits, projects, verification, and guest/employee engagement"}, {"id": "65b13644-20d1-4de7-b9af-45aa8889beb8", "type": "concept", "title": "GSTC Hotel Standard, local community benefit, cultural heritage, human rights, accessibility, green-claim substantiation, and tradeoffs"}], "description": "This subtopic evaluates environmental and social performance through measurable operating practices and credible claims."}, {"id": "829a742d-5050-479e-855d-4b758ab256e7", "type": "subtopic", "title": "Asset protection and capital planning", "children": [{"id": "a3fab76b-1eb7-4e2f-a55b-7a69a7def9ed", "type": "concept", "title": "Operating maintenance, replacement reserve, capital expenditure, renovation cycle, useful life, lifecycle cost, return, risk, and guest disruption"}, {"id": "671020a1-9d1f-4e64-bde0-5e31d8acf33f", "type": "concept", "title": "Property-improvement plan, brand requirement, accessibility upgrade, condition assessment, scope, phasing, procurement, owner approval, and commissioning"}, {"id": "10437f98-d283-4679-b390-6b086f0afc65", "type": "concept", "title": "Inventory displacement, temporary standards, contractor access, dust/noise, safety, communications, contingency, punch list, and post-project review"}], "description": "Students distinguish an urgent repair from a recurring operating expense and a life-cycle capital decision."}]}, {"id": "014c0cf5-c86f-4bea-9293-7e176b987a20", "type": "topic", "title": "Group, Event, VIP, Resort, and Alternative-Lodging Operational Complexity", "description": "Not all stays behave like transient individual business. Students learn to adapt core controls to group blocks, special guests, resorts, extended stays, and alternative accommodations without losing accuracy or service consistency.", "children": [{"id": "d3436512-0324-4867-b27a-caac8380ffbc", "type": "subtopic", "title": "Group and event rooms operations", "children": [{"id": "9780489e-79db-4fe5-9be7-7d246f58e0e1", "type": "concept", "title": "Group block, rooming list, cutoff, pickup, wash, shoulder dates, sub-blocks, staff rooms, upgrades, and attrition awareness"}, {"id": "5747c9e6-7b23-46bb-8d19-533936792aaf", "type": "concept", "title": "Resume, preconference meeting, arrival pattern, key packs, registration desk, luggage, transportation, amenities, VIPs, and accessibility"}, {"id": "6b78a275-62f6-4e69-9b18-5b8c5ddd40ba", "type": "concept", "title": "Master-account routing, incidentals, no-shows, extensions, changes, communication tree, post-event reconciliation, and lessons learned"}], "description": "Students translate a sales commitment into an executable rooms plan across reservations, arrival, stay, billing, and departure."}, {"id": "95ce7c2f-7567-4bea-bdfe-1545958aa474", "type": "subtopic", "title": "VIP, loyalty, long-stay, and special-purpose stays", "children": [{"id": "44ea7049-bbd3-4a96-8fbd-c5294ce828ee", "type": "concept", "title": "VIP criteria, loyalty tiers, preferences, amenities, upgrades, discreet arrival, security coordination, and profile accuracy"}, {"id": "401fd144-f1b5-4a03-a08c-3949420a60b1", "type": "concept", "title": "Extended-stay housekeeping, kitchens, mail, pets, families, medical or recovery stays, crews, government, displaced guests, and relocations"}, {"id": "1d10c4d4-e340-4ac3-b244-ad3344baf54c", "type": "concept", "title": "Consent, sensitive notes, dignitary/privacy protocols, equitable service, exception approval, continuity, and transition planning"}], "description": "This subtopic balances recognition and personalization with privacy, fairness, safety, and sustainable execution."}, {"id": "7f1cedaf-bd47-4c74-9d71-529a0ca3db30", "type": "subtopic", "title": "Resort and alternative-accommodation coordination", "children": [{"id": "90c3f170-9030-4719-ad47-0ef0315844f5", "type": "concept", "title": "Resort transportation, recreation, spa, beach/pool, golf/ski where relevant, children’s programs, villas, residences, and destination services"}, {"id": "ca8953d7-d9d0-4cc9-a32b-092bf798219a", "type": "concept", "title": "Condo-hotel and mixed-use ownership, rental pools, unit variation, owner stays, access rights, maintenance responsibility, and disclosure"}, {"id": "dfba8171-8444-4e37-a4eb-7dea348f407a", "type": "concept", "title": "Vacation rentals, host/platform roles, remote entry, turnover cleaning, local rules, neighborhood impact, safety, accessibility, and service recovery"}], "description": "Students compare the operating complexity introduced by dispersed facilities, activities, residences, and third-party hosts."}]}, {"id": "a6af198a-5efa-4853-a424-b68630188ab8", "type": "topic", "title": "Integrated Rooms Operations Simulation, Analytics, and Management Communication", "description": "The capstone brings demand, people, rooms, guests, systems, risk, quality, and money into one operating day. Students must diagnose, decide, communicate, recover, and learn under uncertainty rather than optimize a single department in isolation.", "children": [{"id": "16ceb462-a253-48d2-b464-fe56426af814", "type": "subtopic", "title": "Simulation design and operational control", "children": [{"id": "0be9187e-ae88-4b8c-9ddb-9de1bdca03f0", "type": "concept", "title": "Property profile, service promise, organization, forecast, arrivals/departures, groups, staffing, room status, maintenance, inventory, and cash position"}, {"id": "c99fb584-521a-4014-833d-e73c316f4887", "type": "concept", "title": "Roles, decision rights, briefings, event injects, guest cases, system outage, safety issue, oversell, quality defect, and demand change"}, {"id": "0fa69d4f-f104-4edc-98c0-e1584441fa40", "type": "concept", "title": "Operating dashboard, task board, decision log, handoffs, escalation, recovery, resource allocation, and time pressure"}], "description": "Students operate a realistic synthetic property across linked shifts with incomplete information and changing conditions."}, {"id": "861d3787-7875-4c12-b40b-5b8142e09ac5", "type": "subtopic", "title": "Analytical diagnosis and decision quality", "children": [{"id": "64fcb520-cb08-44de-bf31-7c2023c1ed16", "type": "concept", "title": "Occupancy, ADR, RevPAR, room status, queue, response time, recovery, housekeeping productivity, defects, labor, costs, and departmental profit"}, {"id": "029e51a0-3749-402c-ab5b-8eba18bcb914", "type": "concept", "title": "Metric definitions, denominators, timestamps, reconciliation, exceptions, missing data, forecast error, benchmarks, and uncertainty ranges"}, {"id": "a20b5f07-1c30-48a2-8baf-a5a22b333533", "type": "concept", "title": "Root cause, options, guest/employee/owner impacts, safety/accessibility/privacy constraints, financial effect, chosen action, and leading indicators"}], "description": "This subtopic asks students to use trustworthy evidence, quantify tradeoffs, and avoid confident stories unsupported by the data."}, {"id": "874a764c-fa62-4c14-b2c5-780e8515ba70", "type": "subtopic", "title": "Management communication and after-action learning", "children": [{"id": "d76466d1-36a7-4832-8a29-7bde4bcc11dc", "type": "concept", "title": "Shift brief, incident update, guest communication, owner/asset-manager summary, dashboard narrative, and executive recommendation"}, {"id": "42c9fe18-32e7-4f3d-a315-1fb0467a7c65", "type": "concept", "title": "Facts, estimates, assumptions, decisions, owners, timing, risks, escalation, confidentiality, tone, and accessible communication"}, {"id": "7cf0a655-78ec-4c63-b14b-9f7beee2ef86", "type": "concept", "title": "Hot wash, structured debrief, what was expected/observed, causal evidence, countermeasures, accountability, follow-up, and simulation reflection"}], "description": "Students communicate different levels of detail to shifts, executives, owners, guests, and partners and then convert experience into improved standard work."}]}], "dbBacked": true}$lodgjson$::jsonb,
