insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('85e7c207-010e-4e37-b8ab-48ebc31e1d5c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Hotel Industry Structure, Ownership, Brands, and the Rooms Division', 'Hotel operations sit inside a network of owners, lenders, asset managers, brands, operators, employees, partners, regulators, and guests. This section gives students the structural vocabulary needed to understand who sets priorities, who controls the experience, and how the rooms division creates value.', 0),
  ('1d0292aa-eb0a-4a0c-aae8-791fb55bae2b', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '85e7c207-010e-4e37-b8ab-48ebc31e1d5c', 'subtopic'::public.curated_course_node_type, 'Hotel classifications and operating contexts', 'Students compare lodging products so that operating choices reflect the property''s market, service promise, physical plant, demand pattern, and guest needs.', 0),
  ('83977033-de78-46c2-8f74-db6880e33cff', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1d0292aa-eb0a-4a0c-aae8-791fb55bae2b', 'concept'::public.curated_course_node_type, 'Full-service, select-service, limited-service, extended-stay, resort, convention, boutique, lifestyle, luxury, economy, and hostel models', null, 0),
  ('9b4195f9-1139-45b4-ba12-73a8c452c6d8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1d0292aa-eb0a-4a0c-aae8-791fb55bae2b', 'concept'::public.curated_course_node_type, 'Urban, airport, highway, destination, mixed-use, all-suite, wellness, casino where legal, and residential or vacation-rental contexts', null, 1),
  ('e73f7458-9ccb-47a1-9a92-4694805da4dd', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1d0292aa-eb0a-4a0c-aae8-791fb55bae2b', 'concept'::public.curated_course_node_type, 'Class, scale, size, location, amenity set, length of stay, demand segment, seasonality, and service intensity', null, 2),
  ('043cf09b-039d-4c81-b2bb-9b361f35a902', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '85e7c207-010e-4e37-b8ab-48ebc31e1d5c', 'subtopic'::public.curated_course_node_type, 'Ownership, management, and affiliation', 'This subtopic clarifies the economic and decision relationships behind a hotel name, because the guest-facing brand may not own or operate the property.', 1),
  ('0412214e-1add-428e-8469-b213d842c6e7', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '043cf09b-039d-4c81-b2bb-9b361f35a902', 'concept'::public.curated_course_node_type, 'Owned-and-operated, management contract, franchise, lease, independent, soft-brand, collection, and third-party management arrangements', null, 0),
  ('408f776b-a525-408a-b0e3-90d70f238805', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '043cf09b-039d-4c81-b2bb-9b361f35a902', 'concept'::public.curated_course_node_type, 'Owner, operator, brand, franchisor, franchisee, asset manager, lender, developer, association, and vendor interests', null, 1),
  ('01e19b6b-5508-4f38-b5c8-54f8be395e5e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '043cf09b-039d-4c81-b2bb-9b361f35a902', 'concept'::public.curated_course_node_type, 'Management fees, franchise fees, brand standards, capital obligations, approval rights, performance tests, and conflicts of interest', null, 2),
  ('d2b4443f-473f-4819-9360-ed6941a2c085', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '85e7c207-010e-4e37-b8ab-48ebc31e1d5c', 'subtopic'::public.curated_course_node_type, 'Rooms division purpose and interdependence', 'Students frame the rooms division as a coordinated service-and-control system rather than a set of isolated departments.', 2),
  ('8b31b03b-d911-4f61-af31-2ec67ed25106', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd2b4443f-473f-4819-9360-ed6941a2c085', 'concept'::public.curated_course_node_type, 'Reservations, front office, guest services, housekeeping, laundry, security, engineering, revenue, sales, finance, and technology interfaces', null, 0),
  ('fd5a3968-16e3-42c7-ab36-f88515a8a6ee', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd2b4443f-473f-4819-9360-ed6941a2c085', 'concept'::public.curated_course_node_type, 'Guest lifecycle, room status, service requests, information handoffs, recovery, revenue capture, cost control, and asset care', null, 1),
  ('52185744-5d9f-4525-9e1e-79681f26960c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd2b4443f-473f-4819-9360-ed6941a2c085', 'concept'::public.curated_course_node_type, 'Guest value, employee experience, owner returns, brand promise, community impact, safety, and regulatory obligations', null, 2),
  ('a5d346b8-222d-4b9a-98a2-3acd26fe9099', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Rooms Division Organization, Leadership, Staffing, and Shift Control', 'Reliable hotel service depends on clear accountability across a continuous, labor-intensive operation. Students learn how organization design, staffing, communication, and manager-on-duty discipline convert forecasts and standards into safe shifts.', 1),
  ('76d8e4e1-8993-4c87-804d-ecdc8d92b7a0', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a5d346b8-222d-4b9a-98a2-3acd26fe9099', 'subtopic'::public.curated_course_node_type, 'Organization, roles, and decision rights', 'Students map who owns each outcome and where decisions must be coordinated or escalated.', 0),
  ('aa1d740a-6a6f-4939-9203-5d0c192a7002', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '76d8e4e1-8993-4c87-804d-ecdc8d92b7a0', 'concept'::public.curated_course_node_type, 'Rooms division executive, front office manager, executive housekeeper, supervisors, agents, attendants, bell/door, concierge, PBX, security, and engineering roles', null, 0),
  ('3c53f3e7-7be0-493c-a1b1-c011322d3356', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '76d8e4e1-8993-4c87-804d-ecdc8d92b7a0', 'concept'::public.curated_course_node_type, 'Organization charts, job descriptions, spans of control, segregation of duties, empowerment limits, and escalation thresholds', null, 1),
  ('668d68a3-7fdb-4bb2-895c-e34800287e37', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '76d8e4e1-8993-4c87-804d-ecdc8d92b7a0', 'concept'::public.curated_course_node_type, 'Owned, managed, franchised, unionized, outsourced, multi-property, and cluster-service variations', null, 2),
  ('a8477851-084f-4fec-a50b-667100874232', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a5d346b8-222d-4b9a-98a2-3acd26fe9099', 'subtopic'::public.curated_course_node_type, 'Workforce planning and productivity', 'This subtopic connects expected demand and workload to the right labor, skills, timing, and contingency capacity.', 1),
  ('1ec13cb8-c912-42a4-a571-a05d470eb669', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a8477851-084f-4fec-a50b-667100874232', 'concept'::public.curated_course_node_type, 'Occupancy, arrivals, departures, stayovers, rooms out of order, service level, room type, group activity, and special projects as workload drivers', null, 0),
  ('0376dc31-a3e3-4ddc-96ff-a11b5aa541d3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a8477851-084f-4fec-a50b-667100874232', 'concept'::public.curated_course_node_type, 'Labor standards, staffing guides, schedules, cross-training, relief pools, overtime, agency labor, call-ins, and schedule fairness', null, 1),
  ('8958c9cc-d21b-4710-87f8-fd0dc298bf81', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a8477851-084f-4fec-a50b-667100874232', 'concept'::public.curated_course_node_type, 'Rooms cleaned per paid hour, labor cost per occupied room, overtime, absence, quality, safety, turnover, and guest impact', null, 2),
  ('a9f5cd4e-a0e7-4dfb-a0b2-3e7cbba3ba7a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a5d346b8-222d-4b9a-98a2-3acd26fe9099', 'subtopic'::public.curated_course_node_type, 'Shift control and leadership routines', 'Students practice the short-cycle management routines that maintain situational awareness and coordinated execution.', 2),
  ('1b5258e8-c6bd-4f31-ba93-ccad9a5ff743', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a9f5cd4e-a0e7-4dfb-a0b2-3e7cbba3ba7a', 'concept'::public.curated_course_node_type, 'Pre-shift briefing, pass-on log, manager-on-duty report, occupancy board, VIP list, group resume, traces, alerts, and unresolved cases', null, 0),
  ('b15a3ec8-ecc1-40db-bce9-bd9a31b56206', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a9f5cd4e-a0e7-4dfb-a0b2-3e7cbba3ba7a', 'concept'::public.curated_course_node_type, 'Visual controls, huddles, walk-throughs, queue monitoring, room-status meetings, break coverage, coaching, and recognition', null, 1),
  ('967a09e6-82e1-4fc2-8755-f26283904882', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a9f5cd4e-a0e7-4dfb-a0b2-3e7cbba3ba7a', 'concept'::public.curated_course_node_type, 'Decision logs, handoff standards, escalation, incident command, after-action review, and next-shift readiness', null, 2),
  ('0884935f-5f5a-4949-befd-455333548cfe', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Reservations, Forecasting, Inventory, and Distribution Channels', 'Reservations translate future demand into commitments, room inventory, cash expectations, and prearrival service information. Students learn to control availability across channels while balancing guest trust, revenue opportunity, and operational capacity.', 2),
  ('af27df17-a129-423d-bde8-4dee38e7d54a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '0884935f-5f5a-4949-befd-455333548cfe', 'subtopic'::public.curated_course_node_type, 'Reservation lifecycle and controls', 'Students trace a booking from inquiry through confirmation, modification, cancellation, arrival, no-show, and record retention.', 0),
  ('86b9ae5a-474a-40ac-a795-ced0253146f0', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'af27df17-a129-423d-bde8-4dee38e7d54a', 'concept'::public.curated_course_node_type, 'Individual, group, corporate, wholesale, package, loyalty, complimentary, walk-in, and guaranteed/non-guaranteed reservations', null, 0),
  ('7621486b-8072-4ae7-8ec2-288b85b9c1d3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'af27df17-a129-423d-bde8-4dee38e7d54a', 'concept'::public.curated_course_node_type, 'Dates, room type, rate plan, occupancy, payment guarantee, deposit, cancellation, accessibility features, preferences, and consent', null, 1),
  ('17670b9f-914f-4bee-85c3-080ac47c43a6', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'af27df17-a129-423d-bde8-4dee38e7d54a', 'concept'::public.curated_course_node_type, 'Confirmation accuracy, change history, duplicate detection, waitlists, traces, prepayment, chargeback evidence, and audit trail', null, 2),
  ('72989973-b5f7-4f86-be1e-9fb0be402ab8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '0884935f-5f5a-4949-befd-455333548cfe', 'subtopic'::public.curated_course_node_type, 'Forecasting and inventory decisions', 'This subtopic uses pace and uncertainty to protect sellable inventory and prepare the operation.', 1),
  ('76841aca-3527-46a1-90b2-d0d7e32dd658', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '72989973-b5f7-4f86-be1e-9fb0be402ab8', 'concept'::public.curated_course_node_type, 'Historical demand, booking pace, pickup, lead time, day of week, seasonality, events, groups, cancellations, no-shows, and wash', null, 0),
  ('306bd590-d924-4776-a011-47d0bb617c7f', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '72989973-b5f7-4f86-be1e-9fb0be402ab8', 'concept'::public.curated_course_node_type, 'Room-type inventory, oversell limits, out-of-order/out-of-service rooms, length-of-stay controls, closed dates, and upgrade paths', null, 1),
  ('6dfeca50-db6a-4768-ba7c-258b1d4ef58e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '72989973-b5f7-4f86-be1e-9fb0be402ab8', 'concept'::public.curated_course_node_type, 'Forecast error, scenario ranges, displacement, sellout risk, walk cost, guest impact, staffing implications, and decision cadence', null, 2),
  ('260efc7c-7de2-4564-8ab3-9f49e7c2f6ab', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '0884935f-5f5a-4949-befd-455333548cfe', 'subtopic'::public.curated_course_node_type, 'Distribution architecture and economics', 'Students map how hotel inventory reaches guests and evaluate channels on net contribution, control, and service consequences.', 2),
  ('adb5b41c-5a6c-4e59-94dc-46c1332eef0a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '260efc7c-7de2-4564-8ab3-9f49e7c2f6ab', 'concept'::public.curated_course_node_type, 'Direct web/voice/app, CRS, GDS, OTA, metasearch, wholesaler, tour operator, TMC, consortia, and channel manager', null, 0),
  ('49aa4975-8595-49b0-9816-16412727813f', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '260efc7c-7de2-4564-8ab3-9f49e7c2f6ab', 'concept'::public.curated_course_node_type, 'Agency, merchant, opaque, package, net-rate, commission, parity, allotment, free-sale, and closed-user-group models', null, 1),
  ('5098a1f6-ce59-4326-a1cb-d94e6d8f28d6', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '260efc7c-7de2-4564-8ab3-9f49e7c2f6ab', 'concept'::public.curated_course_node_type, 'Content and availability accuracy, commission, payment model, fraud, data access, cancellation, service ownership, and net revenue', null, 2),
  ('8c3220b1-4751-4280-9b22-e667fea2c9c3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Prearrival, Arrival, Front Desk, and Guest Accounting', 'Arrival is both a human welcome and a control point for identity, accessibility, room assignment, payment, keys, information, and expectations. Students learn to make front-office processes warm, efficient, secure, and financially accurate.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9314a2ed-5635-409b-9fa9-252ec7d8b87f', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '8c3220b1-4751-4280-9b22-e667fea2c9c3', 'subtopic'::public.curated_course_node_type, 'Prearrival planning and room assignment', 'Students use reservation and operational information to prepare an inclusive, feasible arrival experience before the guest reaches the desk.', 0),
  ('4ebe2eb4-5f0c-4e65-9d10-2e85498876b1', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '9314a2ed-5635-409b-9fa9-252ec7d8b87f', 'concept'::public.curated_course_node_type, 'Arrival lists, room types, accessible-room features, special requests, preferences, loyalty recognition, VIPs, groups, and amenities', null, 0),
  ('3a5f2e34-85c4-4aac-b2a2-95d23db6f7e1', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '9314a2ed-5635-409b-9fa9-252ec7d8b87f', 'concept'::public.curated_course_node_type, 'Pre-registration, digital check-in, mobile key, upsell, transportation, messaging, payment authorization, and consent', null, 1),
  ('ddb31719-fdd6-41eb-94f5-8470c11ddedc', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '9314a2ed-5635-409b-9fa9-252ec7d8b87f', 'concept'::public.curated_course_node_type, 'Room assignment logic, housekeeping/engineering coordination, connecting rooms, early arrival, upgrades, and blocked-room governance', null, 2),
  ('e72a7849-5c84-4b71-a8d1-edb5420b6b51', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '8c3220b1-4751-4280-9b22-e667fea2c9c3', 'subtopic'::public.curated_course_node_type, 'Check-in, keys, and guest information', 'This subtopic combines hospitality with identity, security, privacy, and clear communication.', 1),
  ('c21de65b-bf0e-402b-b76a-3d8abc1d87d4', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e72a7849-5c84-4b71-a8d1-edb5420b6b51', 'concept'::public.curated_course_node_type, 'Welcome, reservation verification, registration, identity checks, payment, incidental authorization, room readiness, and key issuance', null, 0),
  ('44bb1d3d-01fb-4342-80a4-5a760464a308', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e72a7849-5c84-4b71-a8d1-edb5420b6b51', 'concept'::public.curated_course_node_type, 'Accessible communication, service animals, language access, wayfinding, hotel orientation, benefits, fees, policies, and emergency information', null, 1),
  ('62764109-312d-48d5-a6d6-378768acfe3d', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e72a7849-5c84-4b71-a8d1-edb5420b6b51', 'concept'::public.curated_course_node_type, 'Queue design, express/mobile options, identity-protection scripts, key replacement controls, minors and third-party bookings, and exception handling', null, 2),
  ('1a696e12-7165-4dbb-b1ff-38e3cfb30471', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '8c3220b1-4751-4280-9b22-e667fea2c9c3', 'subtopic'::public.curated_course_node_type, 'Guest folios, payments, and departure', 'Students learn how charges move from operating outlets to a controlled guest account and a clear final settlement.', 2),
  ('8d523390-71cd-4819-acf0-b9ae056bbe25', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1a696e12-7165-4dbb-b1ff-38e3cfb30471', 'concept'::public.curated_course_node_type, 'Guest, master, city-ledger, house, and group folios; routing, allowances, rebates, transfers, deposits, and split billing', null, 0),
  ('303b9eb0-26c2-4747-9942-6664b32e472d', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1a696e12-7165-4dbb-b1ff-38e3cfb30471', 'concept'::public.curated_course_node_type, 'Posting, verification, authorization, tokenization concepts, PCI awareness, cash controls, foreign currency where relevant, and chargeback evidence', null, 1),
  ('2b54e8f2-3ee3-40e3-8256-1ea263d2e3b9', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1a696e12-7165-4dbb-b1ff-38e3cfb30471', 'concept'::public.curated_course_node_type, 'Check-out, late departure, invoice delivery, billing questions, express settlement, credit balance, accounts receivable, and record retention', null, 2),
  ('a5401249-1dfb-444b-b8ad-63553d4f1d95', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'In-House Service, Concierge, Communications, and Guest Experience', 'A hotel stay is a sequence of requests, emotions, queues, handoffs, and moments of truth. Students learn to manage that sequence as one experience across departments, channels, cultures, and accessibility needs.', 4),
  ('258d2f76-a31b-4f95-a90b-3d95dc17ee50', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a5401249-1dfb-444b-b8ad-63553d4f1d95', 'subtopic'::public.curated_course_node_type, 'Guest journey and service blueprint', 'Students make the invisible operating system visible so friction and ownership can be improved.', 0),
  ('740ce0a7-2ba7-4691-aa7b-13989c5cb9ae', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '258d2f76-a31b-4f95-a90b-3d95dc17ee50', 'concept'::public.curated_course_node_type, 'Dreaming, booking, prearrival, arrival, stay, departure, post-stay, and return stages', null, 0),
  ('c729bc0a-1234-457f-80ce-44b554147afd', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '258d2f76-a31b-4f95-a90b-3d95dc17ee50', 'concept'::public.curated_course_node_type, 'Guest goals, actions, emotions, waits, uncertainty, touchpoints, frontstage behaviors, backstage processes, systems, and evidence', null, 1),
  ('d4c3eb48-c001-4c3f-8c10-b4f079ef70a2', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '258d2f76-a31b-4f95-a90b-3d95dc17ee50', 'concept'::public.curated_course_node_type, 'Failure points, handoffs, service standards, recovery triggers, accessibility, measures, and accountable owners', null, 2),
  ('d4d09cb9-6112-45d5-8cb4-5bb2ef991293', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a5401249-1dfb-444b-b8ad-63553d4f1d95', 'subtopic'::public.curated_course_node_type, 'Concierge, guest services, and local knowledge', 'This subtopic develops judgment for recommendations, logistics, personalization, and responsible community connection.', 1),
  ('523a2664-ce9f-4448-b786-bf58a8130191', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd4d09cb9-6112-45d5-8cb4-5bb2ef991293', 'concept'::public.curated_course_node_type, 'Bell, door, valet, transportation, luggage, concierge, club lounge, recreation, childcare referral, and business services', null, 0),
  ('f62841be-ec98-4299-af8b-2ff2a6ffa3d4', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd4d09cb9-6112-45d5-8cb4-5bb2ef991293', 'concept'::public.curated_course_node_type, 'Destination knowledge, reservations, ticketing, itineraries, accessibility information, cultural sensitivity, safety, commissions, and disclosure', null, 1),
  ('8d6dea3a-310a-4b4e-8704-c9afee6edeb8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd4d09cb9-6112-45d5-8cb4-5bb2ef991293', 'concept'::public.curated_course_node_type, 'Request capture, confirmation, third-party quality, liability boundaries, vendor escalation, gratuity ethics, and follow-through', null, 2),
  ('01b9e3b0-fbff-4f33-909f-6d81d68ee2cc', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a5401249-1dfb-444b-b8ad-63553d4f1d95', 'subtopic'::public.curated_course_node_type, 'Omnichannel communication and service coordination', 'Students manage one conversation across voice, desk, text, app, email, and departmental workflows.', 2),
  ('76458e98-fb69-4ff1-8566-bfab126f0258', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '01b9e3b0-fbff-4f33-909f-6d81d68ee2cc', 'concept'::public.curated_course_node_type, 'Telephone etiquette, PBX, messaging, chat, email, in-app requests, wake-up calls, lost-property inquiries, and internal radio', null, 0),
  ('dfc443f6-4c4f-494e-b9a3-8d0112284b09', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '01b9e3b0-fbff-4f33-909f-6d81d68ee2cc', 'concept'::public.curated_course_node_type, 'Authentication, privacy, tone, response-time standards, translation, accessibility, consent, records, and escalation', null, 1),
  ('abe03d61-5420-4e28-a269-d9b74564eb3e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '01b9e3b0-fbff-4f33-909f-6d81d68ee2cc', 'concept'::public.curated_course_node_type, 'Case ownership, work orders, dispatch, status visibility, duplicate avoidance, handoff closure, and satisfaction confirmation', null, 2),
  ('77296417-013b-42a6-8b7a-c5dce77f633a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Housekeeping Systems, Cleaning Science, Linen, and Room Readiness', 'Housekeeping protects health, comfort, brand trust, employee safety, room availability, and the physical asset. Students learn to manage cleaning as a measurable production-and-quality system with human and environmental consequences.', 5),
  ('d7989e9e-bfe1-47d2-bdc3-e9e77d4af023', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '77296417-013b-42a6-8b7a-c5dce77f633a', 'subtopic'::public.curated_course_node_type, 'Room-status and cleaning workflow', 'Students coordinate assignments and inspections so sellable rooms are released accurately and on time.', 0),
  ('649e89ee-100c-40ee-97e7-f362e927536a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd7989e9e-bfe1-47d2-bdc3-e9e77d4af023', 'concept'::public.curated_course_node_type, 'Vacant clean/dirty, occupied clean/dirty, inspected, pickup, due out, stayover, do-not-disturb, sleep-out, skipper, out-of-order, and out-of-service statuses', null, 0),
  ('b4f79b93-e09f-4e99-af40-4ad831904ada', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd7989e9e-bfe1-47d2-bdc3-e9e77d4af023', 'concept'::public.curated_course_node_type, 'Morning reports, section assignment, boards or mobile apps, turndown, rush rooms, early arrivals, late checkouts, credits, and reallocation', null, 1),
  ('12b0c0c2-d8c6-4547-8079-8aa7e922d3cb', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd7989e9e-bfe1-47d2-bdc3-e9e77d4af023', 'concept'::public.curated_course_node_type, 'Room attendant, houseperson, inspector, supervisor, front desk, laundry, minibar, engineering, and security handoffs', null, 2),
  ('858d6598-5d74-44ad-b86a-255ac502976b', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '77296417-013b-42a6-8b7a-c5dce77f633a', 'subtopic'::public.curated_course_node_type, 'Cleaning science, safety, and infection prevention', 'This subtopic grounds visible cleanliness in correct chemistry, sequence, dwell time, equipment, ergonomics, and exposure control.', 1),
  ('ff277395-898b-42dd-9f24-68716a09a7cb', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '858d6598-5d74-44ad-b86a-255ac502976b', 'concept'::public.curated_course_node_type, 'Soil identification, detergent/disinfectant distinction, dilution, contact time, high-touch points, cross-contamination, and verification', null, 0),
  ('2302316b-a5c9-41e0-883f-e6b6df98ab21', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '858d6598-5d74-44ad-b86a-255ac502976b', 'concept'::public.curated_course_node_type, 'Safety data sheets, labeling, ventilation, PPE, sharps/biohazards, bloodborne-pathogen procedures, chemical storage, and spill response', null, 1),
  ('37f99e2a-74cb-4a43-936c-1209032c2cd0', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '858d6598-5d74-44ad-b86a-255ac502976b', 'concept'::public.curated_course_node_type, 'Cart design, lifting, bed making, pushing/pulling, repetitive motion, slips, workload, heat, breaks, reporting, and hierarchy of controls', null, 2),
  ('b8c5ad38-a248-4ff2-ae9f-0a1a53d086ad', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '77296417-013b-42a6-8b7a-c5dce77f633a', 'subtopic'::public.curated_course_node_type, 'Linen, amenities, inventory, and quality inspection', 'Students balance availability and presentation with cost, loss, water, energy, waste, and supplier risk.', 2),
  ('12ef2b5c-58fc-4038-955f-48a072d17f1e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b8c5ad38-a248-4ff2-ae9f-0a1a53d086ad', 'concept'::public.curated_course_node_type, 'Par levels, linen flow, laundry capacity, outsourcing, sorting, spotting, washing, drying, finishing, storage, and replacement', null, 0),
  ('59c181f9-f31e-485c-9fe5-dc8722941fc8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b8c5ad38-a248-4ff2-ae9f-0a1a53d086ad', 'concept'::public.curated_course_node_type, 'Guest supplies, uniforms, chemicals, equipment, minibars where applicable, requisitions, cycle counts, shrinkage, and vendor controls', null, 1),
  ('854514c8-bf65-4139-8e1e-d742cb55c316', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b8c5ad38-a248-4ff2-ae9f-0a1a53d086ad', 'concept'::public.curated_course_node_type, 'Inspection sequence, defect taxonomy, scoring, rework, root cause, calibration, preventive maintenance, and trend reporting', null, 2),
  ('960f6084-dbd5-48e9-b6dd-146e08c079e4', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Service Recovery, Complaint Resolution, Loyalty, and Reputation', 'Service failures are tests of empathy, judgment, speed, fairness, and organizational learning. Students practice recovering the relationship while protecting evidence, reducing recurrence, and avoiding promises beyond their authority.', 6),
  ('291c7d5f-7f71-4055-9415-b505524c0833', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '960f6084-dbd5-48e9-b6dd-146e08c079e4', 'subtopic'::public.curated_course_node_type, 'Complaint intake and de-escalation', 'Students learn to hear the guest''s concern accurately, stabilize emotion, and identify the desired and feasible resolution.', 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e6792dc8-338b-4c8b-896a-54a502a0c529', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '291c7d5f-7f71-4055-9415-b505524c0833', 'concept'::public.curated_course_node_type, 'Listen, acknowledge, clarify, empathize, apologize appropriately, verify facts, explain next steps, and set timing', null, 0),
