  ('cc5fe50c-f446-49bb-bf43-3422e0f1b4df', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '291c7d5f-7f71-4055-9415-b505524c0833', 'concept'::public.curated_course_node_type, 'Immediate danger, medical issues, discrimination, harassment, theft, privacy breach, media contact, and legal-threat escalation', null, 2),
  ('a9d0326d-dc24-4c37-a213-8eb136c05298', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '960f6084-dbd5-48e9-b6dd-146e08c079e4', 'subtopic'::public.curated_course_node_type, 'Recovery design and empowerment', 'This subtopic matches remedies to harm, responsibility, relationship value, precedent, and operational feasibility.', 1),
  ('7fc548bc-6c7c-426c-986b-f67f424ee6d2', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a9d0326d-dc24-4c37-a213-8eb136c05298', 'concept'::public.curated_course_node_type, 'Correction, replacement, room move, service, information, apology, fee removal, refund, points, amenity, and follow-up', null, 0),
  ('c5a07bdd-e736-4dd5-97c4-0f7300eb86ec', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a9d0326d-dc24-4c37-a213-8eb136c05298', 'concept'::public.curated_course_node_type, 'Authority limits, approval matrix, consistency, discretion, documentation, fraud patterns, tax/accounting treatment, and vendor recovery', null, 1),
  ('9e56d89d-13dd-47ee-9eab-ec9c283c8fba', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a9d0326d-dc24-4c37-a213-8eb136c05298', 'concept'::public.curated_course_node_type, 'Recovery paradox limits, distributive/procedural/interactional justice, vulnerable guests, and no-retaliation principles', null, 2),
  ('cfd07791-0253-45d1-b6fa-4dc4f53af171', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '960f6084-dbd5-48e9-b6dd-146e08c079e4', 'subtopic'::public.curated_course_node_type, 'Closed-loop learning and reputation', 'Students convert cases and reviews into reliable operational improvements without manipulating public feedback.', 2),
  ('100b4550-bfb7-47c5-a12d-1f22000b41e8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'cfd07791-0253-45d1-b6fa-4dc4f53af171', 'concept'::public.curated_course_node_type, 'Case coding, severity, owner, service-level agreement, root cause, corrective action, verification, and recurrence monitoring', null, 0),
  ('fc6a06db-8161-4234-936f-548863dfc5e8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'cfd07791-0253-45d1-b6fa-4dc4f53af171', 'concept'::public.curated_course_node_type, 'Surveys, review platforms, loyalty feedback, social listening, rating distribution, sentiment, response standards, and competitor context', null, 1),
  ('09fd1e30-ddda-4afe-8e62-a1621b643a49', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'cfd07791-0253-45d1-b6fa-4dc4f53af171', 'concept'::public.curated_course_node_type, 'Authentic reviews, no suppression or fabrication, clear incentives, response privacy, escalation, trend dashboards, and learning reviews', null, 2),
  ('e828d1cf-1706-43a0-adf3-93aae1802216', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'PMS, Hotel Technology Stack, Data, Privacy, Cybersecurity, and Responsible AI', 'Hotel technology coordinates inventory, identity, service, access, payments, and reporting. Students learn the system architecture and controls needed to use automation and AI without sacrificing reliability, privacy, security, accessibility, or human accountability.', 7),
  ('e11bf5bf-d13b-4f3a-a61b-0690bb32713e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e828d1cf-1706-43a0-adf3-93aae1802216', 'subtopic'::public.curated_course_node_type, 'PMS and integrated hotel systems', 'Students map the property management system as part of a wider, failure-prone ecosystem rather than as a single screen.', 0),
  ('6df37357-cf0e-4add-9410-9ede2e72ebd4', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e11bf5bf-d13b-4f3a-a61b-0690bb32713e', 'concept'::public.curated_course_node_type, 'PMS, CRS, booking engine, channel manager, RMS, POS, sales/catering, CRM/CDP, housekeeping, maintenance, PBX, locks, Wi-Fi, payment, and accounting systems', null, 0),
  ('9ea95fc8-be66-4336-b240-17f8a487f4dc', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e11bf5bf-d13b-4f3a-a61b-0690bb32713e', 'concept'::public.curated_course_node_type, 'Profiles, reservations, inventory, rates, room status, folios, interfaces, APIs, batch jobs, timestamps, identifiers, and source-of-truth decisions', null, 1),
  ('0ae90e7b-7e42-44ea-b7c4-c724678cdc78', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e11bf5bf-d13b-4f3a-a61b-0690bb32713e', 'concept'::public.curated_course_node_type, 'Interface monitoring, duplicate profiles, reconciliation, change control, vendor support, downtime, manual fallback, and recovery testing', null, 2),
  ('92790c66-e0ca-48f2-97b7-c738e8eda0b5', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e828d1cf-1706-43a0-adf3-93aae1802216', 'subtopic'::public.curated_course_node_type, 'Data governance, privacy, and cybersecurity', 'This subtopic teaches students to collect less, control access, recognize threats, and protect the guest and property across the data lifecycle.', 1),
  ('52f1be3b-e9c6-431a-9b7a-ece2a27a252c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '92790c66-e0ca-48f2-97b7-c738e8eda0b5', 'concept'::public.curated_course_node_type, 'Data inventory, purpose, consent, minimization, accuracy, retention, deletion, access, portability, logging, and vendor processing', null, 0),
  ('b22be1d8-bb32-4977-9eb4-17af9a495d33', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '92790c66-e0ca-48f2-97b7-c738e8eda0b5', 'concept'::public.curated_course_node_type, 'Identity, payment, travel, location, loyalty, accessibility, preference, incident, employee, biometric, and children''s data sensitivity', null, 1),
  ('958c5040-55e6-40a4-bb75-c3b9c2fea853', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '92790c66-e0ca-48f2-97b7-c738e8eda0b5', 'concept'::public.curated_course_node_type, 'Role-based access, least privilege, multifactor authentication, phishing, social engineering, patching, backups, incident response, and PCI DSS awareness', null, 2),
  ('dfe3a9b3-7436-41d3-a2df-85354e76fc5d', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'e828d1cf-1706-43a0-adf3-93aae1802216', 'subtopic'::public.curated_course_node_type, 'Automation, analytics, and responsible AI', 'Students evaluate whether a technology improves a defined decision or workflow and what new failure modes it creates.', 2),
  ('2b96905a-2094-4388-addd-4249a4b20c1b', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'dfe3a9b3-7436-41d3-a2df-85354e76fc5d', 'concept'::public.curated_course_node_type, 'Chatbots, translation, personalization, forecasting, task routing, scheduling, computer vision, voice, robotics, and generative assistants', null, 0),
  ('b1c4998a-03a8-406b-9f97-2df284971f16', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'dfe3a9b3-7436-41d3-a2df-85354e76fc5d', 'concept'::public.curated_course_node_type, 'Accuracy, hallucination, bias, accessibility, explainability, intellectual property, prompt/data leakage, cyber risk, deskilling, and service authenticity', null, 1),
  ('3346937a-abb0-4abd-8e4f-a05eced633cf', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'dfe3a9b3-7436-41d3-a2df-85354e76fc5d', 'concept'::public.curated_course_node_type, 'Approved use cases, human review, testing, monitoring, override, disclosure, appeal, audit trail, vendor evidence, and retirement criteria', null, 2),
  ('1b62354f-e063-4d3e-b3d3-4f9a8471d8a5', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Night Audit, Internal Controls, Occupancy and Revenue Metrics, and P&L Linkage', 'The business day closes only when operating activity is complete, reconciled, and trustworthy. Students learn to perform night-audit logic, interpret rooms performance, and connect daily decisions to financial statements and management action.', 8),
  ('3bfa425a-dfd1-4b28-a7a6-b991610a60dc', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1b62354f-e063-4d3e-b3d3-4f9a8471d8a5', 'subtopic'::public.curated_course_node_type, 'Business-day close and reconciliation', 'Students sequence the controls required to roll the hotel from one business date to the next.', 0),
  ('13de86c5-e75a-4274-b4a4-6ef34874e53e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '3bfa425a-dfd1-4b28-a7a6-b991610a60dc', 'concept'::public.curated_course_node_type, 'Outstanding postings, no-shows, room/tax, packages, allowances, rebates, transfers, routing, deposits, paid-outs, and house accounts', null, 0),
  ('a831d85f-1cad-42f2-9a5a-bdf210fd56db', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '3bfa425a-dfd1-4b28-a7a6-b991610a60dc', 'concept'::public.curated_course_node_type, 'PMS, POS, payment processor, cash, credit cards, direct bill, interfaces, room status, keys, and occupancy reconciliation', null, 1),
  ('1334e61b-0a80-4e0d-8aed-13ce92274ac4', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '3bfa425a-dfd1-4b28-a7a6-b991610a60dc', 'concept'::public.curated_course_node_type, 'Exception reports, approvals, segregation of duties, audit evidence, backup, system close, distribution, and unresolved-item log', null, 2),
  ('d0523e82-16c4-4aa8-bc79-ee5994898a41', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1b62354f-e063-4d3e-b3d3-4f9a8471d8a5', 'subtopic'::public.curated_course_node_type, 'Rooms metrics and benchmarking', 'This subtopic develops fluency in the measures that explain demand, rate, inventory, and relative performance.', 1),
  ('b011dfc4-c355-400d-92ab-559bbebb4930', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd0523e82-16c4-4aa8-bc79-ee5994898a41', 'concept'::public.curated_course_node_type, 'Rooms available/sold/revenue, occupancy, ADR, RevPAR, double occupancy, average length of stay, cancellation, no-show, and out-of-order percentage', null, 0),
  ('15f2a8a5-d5c9-4514-95bd-93c2c36e3a18', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd0523e82-16c4-4aa8-bc79-ee5994898a41', 'concept'::public.curated_course_node_type, 'Market penetration index, average rate index, revenue generation index, competitive set, fair share, ranking, and confidentiality', null, 1),
  ('af1bfeed-e5e6-432f-b895-615a7b809216', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd0523e82-16c4-4aa8-bc79-ee5994898a41', 'concept'::public.curated_course_node_type, 'Gross versus net revenue, room-type and segment mix, channel cost, complementary metrics, definition control, and false comparisons', null, 2),
  ('b6d4a9ab-8f78-4f66-be3e-e35b443d7d61', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1b62354f-e063-4d3e-b3d3-4f9a8471d8a5', 'subtopic'::public.curated_course_node_type, 'Departmental P&L and management analysis', 'Students connect operational variance to the rooms department and overall hotel economics using lodging-industry account structures.', 2),
  ('7a58667b-50e7-4658-998c-be886b912424', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b6d4a9ab-8f78-4f66-be3e-e35b443d7d61', 'concept'::public.curated_course_node_type, 'Rooms revenue, allowances, payroll, benefits, contract labor, linen, laundry, guest supplies, commissions, reservations, and other expenses', null, 0),
  ('07085139-34ec-48d0-81e7-b5f0cdb38801', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b6d4a9ab-8f78-4f66-be3e-e35b443d7d61', 'concept'::public.curated_course_node_type, 'Budget, forecast, actual, prior year, variance, volume/rate/mix, labor productivity, cost per occupied room, and flow-through', null, 1),
  ('c25c9e0c-2417-403c-9821-3e14e98be921', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b6d4a9ab-8f78-4f66-be3e-e35b443d7d61', 'concept'::public.curated_course_node_type, 'USALI concepts, controllable versus allocated costs, departmental profit, GOP linkage, narrative explanation, and corrective action', null, 2),
  ('a640e1a4-1ed3-42c0-b0d5-6abd3cd45190', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Safety, Security, Accessibility, Risk, Emergency, and Human-Trafficking Awareness', 'Hotels are open, complex environments where care and security must coexist. Students learn prevention, inclusive service, proportionate response, documentation, and escalation while recognizing that law, emergency protocols, and specialized investigations require qualified authority.', 9),
  ('41bee000-7afb-4f68-841a-b834cde3914a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a640e1a4-1ed3-42c0-b0d5-6abd3cd45190', 'subtopic'::public.curated_course_node_type, 'Security, keys, cash, privacy, and incident response', 'Students identify routine controls that protect guests, employees, information, property, and evidence without creating an unwelcoming environment.', 0),
  ('be15f426-4a9e-4ac5-99ce-72a7696e42a4', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '41bee000-7afb-4f68-841a-b834cde3914a', 'concept'::public.curated_course_node_type, 'Master and guest keys, access logs, key replacement, restricted areas, visitor and contractor controls, lost property, safe deposit, and package handling', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e320b77d-5a86-4d62-b3e9-9e585a9d9d9d', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '41bee000-7afb-4f68-841a-b834cde3914a', 'concept'::public.curated_course_node_type, 'Cash, refunds, chargebacks, skimming, fraud, identity theft, social engineering, cyber-physical interfaces, CCTV, and privacy boundaries', null, 1),
  ('36d88fea-5fe7-4ff6-83f1-df52fa982b8c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '41bee000-7afb-4f68-841a-b834cde3914a', 'concept'::public.curated_course_node_type, 'Incident intake, immediate safety, emergency services, manager/security notification, scene preservation, objective report, evidence custody, and follow-up', null, 2),
  ('f17d1364-8b78-4cfc-85c5-bacf563e5af1', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a640e1a4-1ed3-42c0-b0d5-6abd3cd45190', 'subtopic'::public.curated_course_node_type, 'Accessible and inclusive lodging operations', 'This subtopic treats accessibility as an end-to-end guest experience and operating obligation, not only a room-design feature.', 1),
  ('ce17c994-6c73-40f1-b202-d114c5abc21c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'f17d1364-8b78-4cfc-85c5-bacf563e5af1', 'concept'::public.curated_course_node_type, 'Reservation information, accessible-room inventory, feature matching, room assignment, holds, equivalent service, and staff knowledge', null, 0),
  ('edfbf86b-968c-42a8-be54-9fbadb0892a6', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'f17d1364-8b78-4cfc-85c5-bacf563e5af1', 'concept'::public.curated_course_node_type, 'Mobility, hearing, vision, cognitive, communication, digital, dietary, service-animal, and transportation considerations', null, 1),
  ('283580a4-35bf-4235-b18e-0df58a94128a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'f17d1364-8b78-4cfc-85c5-bacf563e5af1', 'concept'::public.curated_course_node_type, 'ADA Title III and 2010 Standards awareness, effective communication, reasonable modifications, web access, maintenance, testing, and escalation to qualified guidance', null, 2),
  ('a1059862-762f-417d-b0aa-7886ad6e6e21', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a640e1a4-1ed3-42c0-b0d5-6abd3cd45190', 'subtopic'::public.curated_course_node_type, 'Emergency readiness and exploitation prevention', 'Students practice a calm, trauma-informed response to low-frequency, high-consequence events and suspicious indicators.', 2),
  ('dd71139f-0da3-4bea-81f7-ca2b2c660836', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a1059862-762f-417d-b0aa-7886ad6e6e21', 'concept'::public.curated_course_node_type, 'Fire, severe weather, power/water/IT outage, medical event, infectious disease, violence, evacuation, shelter, reunification, and business continuity', null, 0),
  ('6dab2dd1-217c-405e-96c2-15c7daf47d16', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a1059862-762f-417d-b0aa-7886ad6e6e21', 'concept'::public.curated_course_node_type, 'Emergency roles, communication redundancy, accessible evacuation, guest accountability, drills, supplies, mutual aid, media protocol, and after-action review', null, 1),
  ('4e02dda1-85ab-4a87-b1a5-d458e7512cc3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a1059862-762f-417d-b0aa-7886ad6e6e21', 'concept'::public.curated_course_node_type, 'Human-trafficking awareness, nonprofiling indicators, privacy and employee safety, property reporting protocol, DHS Blue Campaign resources, and no independent confrontation', null, 2),
  ('ec66d602-12b5-4384-a31c-d27eaab9d9d3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Brand Standards, Quality Assurance, Audits, and Continuous Improvement', 'Standards make a promise repeatable, but quality management must also surface local context, unintended burdens, and changing guest needs. Students learn to measure conformance, experience, process capability, and corrective action together.', 10),
  ('b3ff21fe-21c2-46d9-97b3-be1910963868', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'ec66d602-12b5-4384-a31c-d27eaab9d9d3', 'subtopic'::public.curated_course_node_type, 'Standards architecture and service execution', 'Students translate brand and property promises into observable, trainable, resourced behaviors and conditions.', 0),
  ('f17d35c7-c311-4e59-8402-11ab9128bb7f', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b3ff21fe-21c2-46d9-97b3-be1910963868', 'concept'::public.curated_course_node_type, 'Product, cleanliness, condition, safety, accessibility, service, communication, technology, loyalty, and sustainability standards', null, 0),
  ('4ec2837d-71f5-40ab-97fa-5867f8a2af92', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b3ff21fe-21c2-46d9-97b3-be1910963868', 'concept'::public.curated_course_node_type, 'Standard operating procedures, checklists, job aids, scripts, judgment boundaries, local adaptation, waivers, and version control', null, 1),
  ('9f445b62-06a2-41a7-b9db-c8558826edc3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'b3ff21fe-21c2-46d9-97b3-be1910963868', 'concept'::public.curated_course_node_type, 'Training, tools, staffing, maintenance, supplier specifications, employee feedback, readiness checks, and accountable ownership', null, 2),
  ('aed82804-cc83-40b9-b72d-db454d8c5e9c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'ec66d602-12b5-4384-a31c-d27eaab9d9d3', 'subtopic'::public.curated_course_node_type, 'Quality measurement and auditing', 'This subtopic combines audits with guest, employee, financial, and process evidence so scores do not become the only goal.', 1),
  ('bf5b5825-46e2-4e6e-a5c4-936851f89941', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'aed82804-cc83-40b9-b72d-db454d8c5e9c', 'concept'::public.curated_course_node_type, 'Self-inspection, supervisor inspection, brand audit, mystery shop, guest feedback, complaint data, defect/rework, and operational observation', null, 0),
  ('f8546c30-877f-403d-8c52-9f9d2b01ce22', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'aed82804-cc83-40b9-b72d-db454d8c5e9c', 'concept'::public.curated_course_node_type, 'Sampling, calibration, evidence, scoring, severity, critical failures, consistency, bias, gaming, and appeal', null, 1),
  ('8b1942fa-62f8-4694-863f-e2df29299f6e', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'aed82804-cc83-40b9-b72d-db454d8c5e9c', 'concept'::public.curated_course_node_type, 'Reliability, responsiveness, assurance, empathy, tangibles, effort, satisfaction, recommendation, repeat intent, and behavioral evidence', null, 2),
  ('11685209-189b-4921-8ad1-d6f4d8f5b4a2', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'ec66d602-12b5-4384-a31c-d27eaab9d9d3', 'subtopic'::public.curated_course_node_type, 'Problem solving and continuous improvement', 'Students move from symptoms to verified causes and sustainable process change.', 2),
  ('3dc84221-25c4-439c-b565-799944769f3d', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '11685209-189b-4921-8ad1-d6f4d8f5b4a2', 'concept'::public.curated_course_node_type, 'Problem statement, current condition, standard, gap, stratification, Pareto, process map, five whys, fishbone, and direct observation', null, 0),
  ('8d9a3a1c-f0ae-4c89-8ca9-fe3ebd2ad9b6', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '11685209-189b-4921-8ad1-d6f4d8f5b4a2', 'concept'::public.curated_course_node_type, 'Countermeasure, owner, due date, pilot, risk assessment, standard work, training, change communication, and control plan', null, 1),
  ('328ce675-c5e8-4f35-8e9a-da1efe5ba644', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '11685209-189b-4921-8ad1-d6f4d8f5b4a2', 'concept'::public.curated_course_node_type, 'Plan-do-study-act, leading/lagging measures, unintended effects, verification, sustainment audit, and knowledge sharing', null, 2),
  ('be00ef8e-31bd-4072-be76-dc7ddd65e22a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Facilities, Maintenance, Sustainability, Asset Protection, and Capital Planning', 'The guestroom product is a physical asset consumed every day. Students learn how rooms operations, engineering, finance, ownership, and sustainability systems coordinate to protect availability, safety, comfort, and long-term value.', 11),
  ('1ac81c2f-f0e0-4790-8c7d-5d9f3790bdee', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'be00ef8e-31bd-4072-be76-dc7ddd65e22a', 'subtopic'::public.curated_course_node_type, 'Preventive maintenance and room availability', 'Students connect defect capture and planned maintenance to fewer guest failures and more sellable inventory.', 0),
  ('24133de1-3144-4519-a695-b2997223adfe', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1ac81c2f-f0e0-4790-8c7d-5d9f3790bdee', 'concept'::public.curated_course_node_type, 'Guestroom, corridor, public-area, elevator, HVAC, plumbing, electrical, lighting, locks, life-safety, pool/spa, and exterior systems', null, 0),
  ('292adc28-15e2-4795-b0a9-7be214afb14c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1ac81c2f-f0e0-4790-8c7d-5d9f3790bdee', 'concept'::public.curated_course_node_type, 'Work requests, priority, dispatch, access, parts, technician notes, quality check, reopening, backlog, and repeat-defect analysis', null, 1),
  ('2a98022f-aae3-4728-8059-35b8665cbbdf', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '1ac81c2f-f0e0-4790-8c7d-5d9f3790bdee', 'concept'::public.curated_course_node_type, 'Out-of-order versus out-of-service governance, downtime, lost room revenue, preventive schedules, inspections, and condition index', null, 2),
  ('9009eacb-f98c-472f-8e01-a0187c27112a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'be00ef8e-31bd-4072-be76-dc7ddd65e22a', 'subtopic'::public.curated_course_node_type, 'Resource efficiency and sustainable operations', 'This subtopic evaluates environmental and social performance through measurable operating practices and credible claims.', 1),
  ('4b26eec4-0816-4ed6-b22a-7c005b2fc365', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '9009eacb-f98c-472f-8e01-a0187c27112a', 'concept'::public.curated_course_node_type, 'Energy, water, waste, linen/towel programs, chemicals, refrigerants, indoor air, biodiversity, purchasing, food/amenity waste, and single-use materials', null, 0),
  ('07174b51-0078-41c0-8d75-49fcb2f689b3', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '9009eacb-f98c-472f-8e01-a0187c27112a', 'concept'::public.curated_course_node_type, 'Meters, baselines, intensity measures, targets, occupancy/weather normalization, audits, projects, verification, and guest/employee engagement', null, 1),
  ('65b13644-20d1-4de7-b9af-45aa8889beb8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '9009eacb-f98c-472f-8e01-a0187c27112a', 'concept'::public.curated_course_node_type, 'GSTC Hotel Standard, local community benefit, cultural heritage, human rights, accessibility, green-claim substantiation, and tradeoffs', null, 2),
  ('829a742d-5050-479e-855d-4b758ab256e7', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'be00ef8e-31bd-4072-be76-dc7ddd65e22a', 'subtopic'::public.curated_course_node_type, 'Asset protection and capital planning', 'Students distinguish an urgent repair from a recurring operating expense and a life-cycle capital decision.', 2),
  ('a3fab76b-1eb7-4e2f-a55b-7a69a7def9ed', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '829a742d-5050-479e-855d-4b758ab256e7', 'concept'::public.curated_course_node_type, 'Operating maintenance, replacement reserve, capital expenditure, renovation cycle, useful life, lifecycle cost, return, risk, and guest disruption', null, 0),
  ('671020a1-9d1f-4e64-bde0-5e31d8acf33f', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '829a742d-5050-479e-855d-4b758ab256e7', 'concept'::public.curated_course_node_type, 'Property-improvement plan, brand requirement, accessibility upgrade, condition assessment, scope, phasing, procurement, owner approval, and commissioning', null, 1),
  ('10437f98-d283-4679-b390-6b086f0afc65', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '829a742d-5050-479e-855d-4b758ab256e7', 'concept'::public.curated_course_node_type, 'Inventory displacement, temporary standards, contractor access, dust/noise, safety, communications, contingency, punch list, and post-project review', null, 2),
  ('014c0cf5-c86f-4bea-9293-7e176b987a20', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Group, Event, VIP, Resort, and Alternative-Lodging Operational Complexity', 'Not all stays behave like transient individual business. Students learn to adapt core controls to group blocks, special guests, resorts, extended stays, and alternative accommodations without losing accuracy or service consistency.', 12),
  ('d3436512-0324-4867-b27a-caac8380ffbc', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '014c0cf5-c86f-4bea-9293-7e176b987a20', 'subtopic'::public.curated_course_node_type, 'Group and event rooms operations', 'Students translate a sales commitment into an executable rooms plan across reservations, arrival, stay, billing, and departure.', 0),
  ('9780489e-79db-4fe5-9be7-7d246f58e0e1', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd3436512-0324-4867-b27a-caac8380ffbc', 'concept'::public.curated_course_node_type, 'Group block, rooming list, cutoff, pickup, wash, shoulder dates, sub-blocks, staff rooms, upgrades, and attrition awareness', null, 0),
  ('5747c9e6-7b23-46bb-8d19-533936792aaf', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd3436512-0324-4867-b27a-caac8380ffbc', 'concept'::public.curated_course_node_type, 'Resume, preconference meeting, arrival pattern, key packs, registration desk, luggage, transportation, amenities, VIPs, and accessibility', null, 1);
