  ('6b78a275-62f6-4e69-9b18-5b8c5ddd40ba', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'd3436512-0324-4867-b27a-caac8380ffbc', 'concept'::public.curated_course_node_type, 'Master-account routing, incidentals, no-shows, extensions, changes, communication tree, post-event reconciliation, and lessons learned', null, 2),
