  ('44ea7049-bbd3-4a96-8fbd-c5294ce828ee', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '95ce7c2f-7567-4bea-bdfe-1545958aa474', 'concept'::public.curated_course_node_type, 'VIP criteria, loyalty tiers, preferences, amenities, upgrades, discreet arrival, security coordination, and profile accuracy', null, 0),
  ('401fd144-f1b5-4a03-a08c-3949420a60b1', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '95ce7c2f-7567-4bea-bdfe-1545958aa474', 'concept'::public.curated_course_node_type, 'Extended-stay housekeeping, kitchens, mail, pets, families, medical or recovery stays, crews, government, displaced guests, and relocations', null, 1),
  ('1d10c4d4-e340-4ac3-b244-ad3344baf54c', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '95ce7c2f-7567-4bea-bdfe-1545958aa474', 'concept'::public.curated_course_node_type, 'Consent, sensitive notes, dignitary/privacy protocols, equitable service, exception approval, continuity, and transition planning', null, 2),
  ('7f1cedaf-bd47-4c74-9d71-529a0ca3db30', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '014c0cf5-c86f-4bea-9293-7e176b987a20', 'subtopic'::public.curated_course_node_type, 'Resort and alternative-accommodation coordination', 'Students compare the operating complexity introduced by dispersed facilities, activities, residences, and third-party hosts.', 2),
  ('90c3f170-9030-4719-ad47-0ef0315844f5', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '7f1cedaf-bd47-4c74-9d71-529a0ca3db30', 'concept'::public.curated_course_node_type, 'Resort transportation, recreation, spa, beach/pool, golf/ski where relevant, children’s programs, villas, residences, and destination services', null, 0),
  ('ca8953d7-d9d0-4cc9-a32b-092bf798219a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '7f1cedaf-bd47-4c74-9d71-529a0ca3db30', 'concept'::public.curated_course_node_type, 'Condo-hotel and mixed-use ownership, rental pools, unit variation, owner stays, access rights, maintenance responsibility, and disclosure', null, 1),
  ('dfba8171-8444-4e37-a4eb-7dea348f407a', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '7f1cedaf-bd47-4c74-9d71-529a0ca3db30', 'concept'::public.curated_course_node_type, 'Vacation rentals, host/platform roles, remote entry, turnover cleaning, local rules, neighborhood impact, safety, accessibility, and service recovery', null, 2),
  ('a6af198a-5efa-4853-a424-b68630188ab8', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', null, 'topic'::public.curated_course_node_type, 'Integrated Rooms Operations Simulation, Analytics, and Management Communication', 'The capstone brings demand, people, rooms, guests, systems, risk, quality, and money into one operating day. Students must diagnose, decide, communicate, recover, and learn under uncertainty rather than optimize a single department in isolation.', 13),
  ('16ceb462-a253-48d2-b464-fe56426af814', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a6af198a-5efa-4853-a424-b68630188ab8', 'subtopic'::public.curated_course_node_type, 'Simulation design and operational control', 'Students operate a realistic synthetic property across linked shifts with incomplete information and changing conditions.', 0),
  ('0be9187e-ae88-4b8c-9ddb-9de1bdca03f0', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '16ceb462-a253-48d2-b464-fe56426af814', 'concept'::public.curated_course_node_type, 'Property profile, service promise, organization, forecast, arrivals/departures, groups, staffing, room status, maintenance, inventory, and cash position', null, 0),
  ('c99fb584-521a-4014-833d-e73c316f4887', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '16ceb462-a253-48d2-b464-fe56426af814', 'concept'::public.curated_course_node_type, 'Roles, decision rights, briefings, event injects, guest cases, system outage, safety issue, oversell, quality defect, and demand change', null, 1),
  ('0fa69d4f-f104-4edc-98c0-e1584441fa40', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '16ceb462-a253-48d2-b464-fe56426af814', 'concept'::public.curated_course_node_type, 'Operating dashboard, task board, decision log, handoffs, escalation, recovery, resource allocation, and time pressure', null, 2),
  ('861d3787-7875-4c12-b40b-5b8142e09ac5', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a6af198a-5efa-4853-a424-b68630188ab8', 'subtopic'::public.curated_course_node_type, 'Analytical diagnosis and decision quality', 'This subtopic asks students to use trustworthy evidence, quantify tradeoffs, and avoid confident stories unsupported by the data.', 1),
  ('64fcb520-cb08-44de-bf31-7c2023c1ed16', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '861d3787-7875-4c12-b40b-5b8142e09ac5', 'concept'::public.curated_course_node_type, 'Occupancy, ADR, RevPAR, room status, queue, response time, recovery, housekeeping productivity, defects, labor, costs, and departmental profit', null, 0),
  ('029e51a0-3749-402c-ab5b-8eba18bcb914', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '861d3787-7875-4c12-b40b-5b8142e09ac5', 'concept'::public.curated_course_node_type, 'Metric definitions, denominators, timestamps, reconciliation, exceptions, missing data, forecast error, benchmarks, and uncertainty ranges', null, 1),
  ('a20b5f07-1c30-48a2-8baf-a5a22b333533', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '861d3787-7875-4c12-b40b-5b8142e09ac5', 'concept'::public.curated_course_node_type, 'Root cause, options, guest/employee/owner impacts, safety/accessibility/privacy constraints, financial effect, chosen action, and leading indicators', null, 2),
  ('874a764c-fa62-4c14-b2c5-780e8515ba70', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', 'a6af198a-5efa-4853-a424-b68630188ab8', 'subtopic'::public.curated_course_node_type, 'Management communication and after-action learning', 'Students communicate different levels of detail to shifts, executives, owners, guests, and partners and then convert experience into improved standard work.', 2),
  ('d76466d1-36a7-4832-8a29-7bde4bcc11dc', 'e6f7a8b9-0c1d-4e21-8f30-4a5b6c7d8e11', '874a764c-fa62-4c14-b2c5-780e8515ba70', 'concept'::public.curated_course_node_type, 'Shift brief, incident update, guest communication, owner/asset-manager summary, dashboard narrative, and executive recommendation', null, 0),
